import{_ as i,C as o,c as t,o as a,aa as n,G as l}from"./chunks/framework.Cn7WEiMX.js";const h=JSON.parse('{"title":"特殊纹理文件类型","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/mod-support/special-texture-file-types.md","filePath":"wiki/Dynmap/mod-support/special-texture-file-types.md"}'),s={name:"wiki/Dynmap/mod-support/special-texture-file-types.md"};function p(u,e,r,g,_,m){const c=o("NolebaseGitContributors"),d=o("NolebaseGitChangelog");return a(),t("div",null,[e[0]||(e[0]=n(`<h1 id="特殊纹理文件类型" tabindex="-1">特殊纹理文件类型 <a class="header-anchor" href="#特殊纹理文件类型" aria-label="Permalink to &quot;特殊纹理文件类型&quot;">​</a></h1> <p>除了默认格式（<code>xcount</code> 乘以 <code>ycount</code> 的平面网格），Dynmap 还支持一些特殊格式的纹理文件。目前定义类型包括如下：</p> <ul><li><code>GRID</code> - 默认类型，对应 <code>xcount</code> 单位宽，<code>ycount</code> 单位高的方形纹理。每个纹理边长都需要为 2 的次幂。纹理的序号从左上角（<code>index=0</code>）逐渐移动到第一行右侧（为 <code>index=&lt;xcount&gt;-1</code>），然后转到下一行从左往右数第一格（<code>index=&lt;xcount&gt;</code>），依此类推。</li> <li><code>CHEST</code> - 应用于小型箱子的纹理排版格式。序号值为：
<ul><li><code>0</code>：箱子顶部</li> <li><code>1</code>：箱子左面</li> <li><code>2</code>：箱子右面</li> <li><code>3</code>：箱子正面</li> <li><code>4</code>：箱子背面</li> <li><code>5</code>：箱子底面</li></ul></li> <li><code>BITCHEST</code> - 应用于大型箱子的纹理排版格式。序号值为：
<ul><li><code>0</code>：箱子顶部 - 左半部分</li> <li><code>1</code>：箱子顶部 - 右半部分</li> <li><code>2</code>：箱子前面 - 左半部分</li> <li><code>3</code>：箱子前面 - 右半部分</li> <li><code>4</code>：箱子左面</li> <li><code>5</code>：箱子右面</li> <li><code>6</code>：箱子背面 - 左半部分</li> <li><code>7</code>：箱子背面 - 右半部分</li> <li><code>8</code>：箱子底面 - 左半部分</li> <li><code>9</code>：箱子底面 - 右半部分</li></ul></li> <li><code>SIGN</code> - 应用于告示牌的纹理排版格式。序号值为：
<ul><li><code>0</code>：贴墙告示牌正面</li> <li><code>1</code>：贴墙告示牌背面</li> <li><code>2</code>：贴墙告示牌顶面</li> <li><code>3</code>：贴墙告示牌底面</li> <li><code>4</code>：贴墙告示牌左面</li> <li><code>5</code>：贴墙告示牌右面</li> <li><code>6</code>：立柱告示牌正面</li> <li><code>7</code>：立柱告示牌背面</li> <li><code>8</code>：立柱告示牌左面</li> <li><code>9</code>：立柱告示牌右面</li></ul></li> <li><code>SKIN</code> - 应用于玩家（或其他人形实体皮肤）的纹理排版格式。序号值为：
<ul><li><code>0</code>：头部正面</li> <li><code>1</code>：头部左面</li> <li><code>2</code>：头部右面</li> <li><code>3</code>：头部背面</li> <li><code>4</code>：头部顶面</li> <li><code>5</code>：头部底面</li></ul></li> <li><code>CUSTOM</code> - 这个格式更加灵活，允许提取任意矩形纹理用作索引纹理。<code>&lt;xcount&gt;</code> 与 <code>&lt;ycount&gt;</code> 值用于检测纹理图片的比例（假设正常纹理长宽为 <code>&lt;xcount&gt;</code> 及 <code>&lt;ycount&gt;</code> 的 16 整数倍）。<code>texturefile</code> 属性定义需要为每个纹理索引包含至少一个 <code>tile&lt;数字&gt;=</code> 属性（<code>数字</code> 为 0、1、2 等）。字段对应值如下：
<ul><li>tile=:/:</li></ul></li></ul> <p>或者，可以这样：</p> <div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  tile&lt;数字&gt;=&lt;X 轴源偏移&gt;:&lt;Y 轴源偏移&gt;/&lt;X 轴&gt;:&lt;Y 轴&gt;/&lt;X 轴目标偏移&gt;:&lt;Y 轴目标偏移&gt;</span></span></code></pre></div><p>参数解释：</p> <ul><li><code>&lt;X 轴源偏移&gt;</code> 为文件内左上角纹理的 X 轴起始点，单位为比例像素</li> <li><code>&lt;Y 轴源偏移&gt;</code> 为文件内左上角纹理的 Y 轴起始点，单位为比例像素</li> <li><code>&lt;X 轴&gt;</code>：为文件内的水平纹理，单位为比例像素</li> <li><code>&lt;Y 轴&gt;</code>：为文件内的垂直纹理，单位为比例像素</li> <li><code>&lt;X 轴目标偏移&gt;</code>：为目标文件内的左上角纹理的 X 轴起始点（默认为 0），单位为比例像素</li> <li><code>&lt;Y 轴目标偏移&gt;</code>：为目标文件内的左上角纹理的 Y 轴起始点（默认为 0），单位为比例像素</li></ul> `,13)),l(c),l(d)])}const y=i(s,[["render",p]]);export{h as __pageData,y as default};
